        /// <summary>
        /// Returns a <see cref="ColumnsEnum"/>
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        /// <exception cref="NotImplementedException"></exception>
        public static ColumnsEnum ColumnsEnumFromString(string value)
        {
            if (value.Equals("SPEND_IN_MICRO_DOLLAR"))
                return ColumnsEnum.SPENDINMICRODOLLAR;

            if (value.Equals("SPEND_IN_MICRO_US_DOLLAR"))
                return ColumnsEnum.SPENDINMICROUSDOLLAR;

            if (value.Equals("BONUS_SPEND_IN_MICRO_DOLLAR"))
                return ColumnsEnum.BONUSSPENDINMICRODOLLAR;

